    'cols':   ('--cols <columns>', None),
    'len':    ('--len <len>', None),
    'format': ('--format <format>', "  [possible values: o, x, X, b]\n"),
    'color':  ('--color <color>', "  [possible values: 0, 1]\n"),
    'array':  ('--array <array_format>', "  [possible values: r, c, g, p, k, j, s, f]\n"),
    'func':   ('--func <func_length>', None),
    'places': ('--places <func_places>', None),
    'prefix': ('--prefix <prefix>', "  [possible values: 0, 1]\n"),
}

SHORT_TO_KEY = {'c':'cols','l':'len','f':'format','t':'color','a':'array','u':'func','p':'places','r':'prefix'}
LONG_TO_KEY = {'cols':'cols','len':'len','format':'format','color':'color','array':'array','func':'func','places':'places','prefix':'prefix'}

class UsageError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg)
        self.code = code

class ParseIntError(Exception):
    def __init__(self, kind, detail):
        self.kind = kind
        self.detail = detail

def parse_uint(s):
    # Rust's usize::from_str accepts only decimal digits, optional leading + is allowed by Python
    # but not by Rust for unsigned integers; keep the common observed behavior.
    if s == '':
        raise ParseIntError('Empty', 'cannot parse integer from empty string')
    if not all('0' <= ch <= '9' for ch in s):
        raise ParseIntError('InvalidDigit', 'invalid digit found in string')
    try:
        val = int(s, 10)
    except Exception:
        raise ParseIntError('InvalidDigit', 'invalid digit found in string')
    # Approximate 64-bit usize overflow message/kind.
    if val > 18446744073709551615:
        raise ParseIntError('PosOverflow', 'number too large to fit in target type')
    return val

def int_error(optlabel, e):
    return f"{optlabel} <integer> expected. ParseIntError {{ kind: {e.kind} }}\nerror: {e.detail}\n"

def missing_value(key):
    opt, possible = OPTION_INFO[key]
    s = f"error: a value is required for '{opt}' but none was supplied\n"
    if possible:
        s += possible
    s += "\nFor more information, try '--help'.\n"
    return s

def duplicate_error(key):
    opt, _ = OPTION_INFO[key]
    return f"error: the argument '{opt}' cannot be used multiple times\n\n" + USAGE

def invalid_value(key, val):
    opt, possible = OPTION_INFO[key]
    s = f"error: invalid value '{val}' for '{opt}'\n"
    if possible:
        s += possible
    s += "\nFor more information, try '--help'.\n"
    return s

def unexpected(arg, tip=True):
    s = f"error: unexpected argument '{arg}' found\n\n"
    if tip and arg.startswith('-'):
        s += f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
    s += USAGE
    return s

def opt_int_label(key):
    if key == 'cols': return '-c, --cols'
    if key == 'len': return '-l, --len'
    if key == 'func': return '-u, --func'
    if key == 'places': return '-p, --places'
    return '--' + key

def normalize_short_value(raw):
    # clap accepts -c=4 as value 4 for value-taking short options.
    if raw.startswith('='):
        return raw[1:]
    return raw

def parse_args(argv):
    opts = {
        'cols': None, 'len': None, 'format': None, 'color': None,
        'array': None, 'func': None, 'places': None, 'prefix': None,
    }
    seen = set()
    inputfile = None
    i = 0
    after_dd = False
    while i < len(argv):
        arg = argv[i]
        if not after_dd and arg == '--':
            after_dd = True; i += 1; continue
        if not after_dd and arg in ('-h','--help'):
            print(HELP, end=''); raise SystemExit(0)
        if not after_dd and arg in ('-V','--version'):
            print('hx 0.7.0'); raise SystemExit(0)
        if not after_dd and arg.startswith('--') and arg != '--':
            body = arg[2:]
            if '=' in body:
                name, val = body.split('=',1)
                has_inline = True
            else:
                name, val = body, None
                has_inline = False
            if name not in LONG_TO_KEY:
                raise UsageError(unexpected(arg))
            key = LONG_TO_KEY[name]
            if key in seen:
                raise UsageError(duplicate_error(key))
            seen.add(key)
            if not has_inline:
                if i+1 >= len(argv) or argv[i+1].startswith('-'):
                    raise UsageError(missing_value(key))
                val = argv[i+1]; i += 1
            set_option(opts, key, val)
            i += 1; continue
        if not after_dd and arg.startswith('-') and arg != '-':
            # Single short value option: -c4, -c 4, -c=4.  Multiple-option clusters are
            # not used by this interface; the first char consumes the remainder as value.
            ch = arg[1:2]
