                if global_i != n-1:
                    elem += '; '
            else:
                elem = f"0x{b:02x}"
                if kind == 'g':
                    elem += ', '
                else:
                    if global_i != n-1:
                        elem += ', '
            line += elem
        sys.stdout.write(line + '\n')
    sys.stdout.write(footers[kind])

