                # options another option means missing, and an unknown dash token is reported
                # as unexpected.  This matches the common cases observed.
                if nxt.startswith('-'):
                    if key in ('format','array','color','prefix') and nxt == '-':
                        val = nxt; i += 1
                    elif key in ('format','array','color','prefix') and not (len(nxt) >= 2 and nxt[1:2] in SHORT_TO_KEY):
                        val = nxt; i += 1
                    elif nxt in ('-h','--help') or nxt in ('-V','--version') or (len(nxt)>=2 and nxt[1:2] in SHORT_TO_KEY) or nxt.startswith('--'):
                        raise UsageError(missing_value(key))
                    else:
                        raise UsageError(unexpected(nxt))
                else:
                    val = nxt; i += 1
            set_option(opts, key, val)
            i += 1; continue
        # positional
        if inputfile is None:
            inputfile = arg
        else:
            raise UsageError(unexpected(arg, tip=False))
        i += 1
    return opts, inputfile

def set_option(opts, key, val):
    if key in ('format','array','color','prefix'):
        allowed = {
            'format': {'o','x','X','b'},
            'array': set('rcgpkjsf'),
            'color': {'0','1'},
            'prefix': {'0','1'},
        }[key]
        if val not in allowed:
            raise UsageError(invalid_value(key, val))
        opts[key] = val
    elif key in ('cols','len','func'):
        try:
            opts[key] = parse_uint(val)
        except ParseIntError as e:
            raise UsageError(int_error(opt_int_label(key), e), code=1)
    elif key == 'places':
        # The original stores this lazily and only parses it when --func is active.
        opts[key] = val

def read_input(path, limit):
    try:
        if path is not None:
            with open(path, 'rb') as f:
                data = f.read()
        else:
            data = sys.stdin.buffer.read()
    except OSError as e:
        sys.stderr.write(f"error: {e.strerror} (os error {e.errno})\n")
        sys.exit(1)
    if limit is not None and limit != 0:
        data = data[:limit]
    return data

def byte_token(b, fmt='x', prefix=True):
    if fmt is None: fmt = 'x'
    if fmt == 'x':
        s = f"{b:02x}"; return ('0x' + s) if prefix else s
    if fmt == 'X':
        s = f"{b:02X}"; return ('0x' + s) if prefix else s
    if fmt == 'o':
        s = f"{b:04o}"; return ('0o' + s) if prefix else s
    if fmt == 'b':
        s = f"{b:08b}"; return ('0b' + s) if prefix else s
    s = f"{b:02x}"; return ('0x' + s) if prefix else s

def color_code(b):
    return 22 if b == 0 else b

def colorize(s, b, enable):
    if not enable:
        return s
    return f"\033[38;5;{color_code(b)}m{s}\033[0m"

def ascii_char(b):
    return chr(b) if 32 <= b <= 126 else '.'

def hexdump(data, opts):
    cols_val = opts['cols'] if opts['cols'] is not None else 10
    step = cols_val if cols_val > 0 else 1
    fmt = opts['format'] or 'x'
    prefix = (opts['prefix'] != '0')
    tok_width = len(byte_token(0, fmt, prefix))
    # color default only on TTY and not when NO_COLOR is present; -t 1 forces, -t 0 disables.
    if opts['color'] == '1':
        use_color = True
    elif opts['color'] == '0':
        use_color = False
    else:
        use_color = sys.stdout.isatty() and ('NO_COLOR' not in os.environ)
    out=[]
    n = len(data)
    # Number of rows includes an extra empty row when the length is exactly divisible by step,
    # including zero-length input.
    rows = n // step + 1 if n % step == 0 else (n + step - 1)//step
    for r in range(rows):
        off = r * step
        chunk = data[off:off+step]
        line = f"0x{off:06x}: "
        slots = cols_val
        if slots < 0: slots = 0
        if slots == 0:
            # The byte display still emits one byte per row for --cols 0, but there are no
            # padding slots on the final empty row.
            for b in chunk[:1]:
                line += colorize(byte_token(b, fmt, prefix), b, use_color) + ' '
        else:
            for j in range(slots):
                if j < len(chunk):
                    b = chunk[j]
                    line += colorize(byte_token(b, fmt, prefix), b, use_color) + ' '
                else:
                    line += ' ' * (tok_width + 1)
        # ASCII rendering contains exactly the actual chunk bytes.
        for b in chunk[:(step if cols_val == 0 else max(cols_val,0))]:
            line += colorize(ascii_char(b), b, use_color)
        out.append(line + '\n')
    out.append(f"   bytes: {n}\n")
    sys.stdout.write(''.join(out))

def array_elements(data, cols):
    step = cols if cols and cols > 0 else 1
    n = len(data)
    rows = n // step + 1 if n % step == 0 else (n + step - 1)//step
    for r in range(rows):
        off = r*step
        yield off, data[off:off+step]

def array_output(data, opts):
    kind = opts['array']
    cols = opts['cols'] if opts['cols'] is not None else 10
    n = len(data)
    headers = {
        'r': f"let ARRAY: [u8; {n}] = [\n",
        'c': f"unsigned char ARRAY[{n}] = {{\n",
        'g': f"a := [{n}]byte{{\n",
        'p': "a = [\n",
        'k': "val a = byteArrayOf(\n",
        'j': "byte[] a = new byte[]{\n",
        's': "let a: [UInt8] = [\n",
        'f': "let a = [|\n",
    }
    footers = {
        'r': "];\n", 'c': "};\n", 'g': "}\n", 'p': "]\n", 'k': ")\n",
        'j': "};\n", 's': "]\n", 'f': "|]\n",
    }
    sys.stdout.write(headers[kind])
    for off, chunk in array_elements(data, cols):
        line = '    '
        for idx, b in enumerate(chunk):
            global_i = off + idx
            if kind == 'f':
                elem = f"0x{b:02x}uy"
                if global_i != n-1:
                    elem += '; '
            else:
                elem = f"0x{b:02x}"
                if kind == 'g':
                    elem += ', '
                else:
                    if global_i != n-1:
                        elem += ', '
            line += elem
        sys.stdout.write(line + '\n')
    sys.stdout.write(footers[kind])

def func_output(opts):
    n = opts['func']
    places = 4
    if opts['places'] is not None:
        try:
            places = parse_uint(opts['places'])
        except ParseIntError as e:
            raise UsageError(int_error('-p, --places', e), code=1)
    if n == 0:
        sys.stdout.write('\n')
        return
    for i in range(n):
        val = math.sin(i * math.pi / (2.0 * n))
        sys.stdout.write(f"{val:.{places}f},")
        if (i + 1) % 10 == 0:
            sys.stdout.write('\n')
    sys.stdout.write('\n')

def main():
    try:
        opts, inputfile = parse_args(sys.argv[1:])
        if opts['func'] is not None:
            func_output(opts)
            return 0
        data = read_input(inputfile, opts['len'])
        if opts['array'] is not None:
            array_output(data, opts)
        else:
            hexdump(data, opts)
        return 0
    except UsageError as e:
        sys.stderr.write(str(e))
        return e.code
    except BrokenPipeError:
        return 0

if __name__ == '__main__':
    sys.exit(main())
